create table "<SCHEMA>"."Resource" (alias varchar(255), category varchar(255), pattern jsonb, meta jsonb);
insert into "<SCHEMA>"."Resource" select * from json_populate_recordset(null::"<SCHEMA>"."Resource", $j$[{"alias":"anonymous:ACCOUNT","category":"ACCOUNT","pattern":{"categories":"{Anonymous,Shadow}"},"meta":{"description":"Unauthenticated users (includes Anonymous and Shadow categories)"}},{"alias":"any:ACCOUNT","category":"ACCOUNT","pattern":null,"meta":{"description":"All account categories (no pattern = match all)"}},{"alias":"any:API","category":"API","pattern":null,"meta":{"description":"All API endpoints (no pattern = match all, for default deny)"}},{"alias":"auth.anonymous:API","category":"API","pattern":{"endpoint":"v2.auth.password.{signup,signin,reset.*,email.*}"},"meta":{"endpoints":["v2.auth.password.signup","v2.auth.password.signin","v2.auth.password.reset.request","v2.auth.password.reset.complete","v2.auth.password.email.verify","v2.auth.password.email.resend"],"description":"Anonymous auth endpoints (signup, signin, reset, email verification)"}},{"alias":"auth.telegram:API","category":"API","pattern":{"endpoint":"v2.auth.telegram.{initiate,poll}"},"meta":{"endpoints":["v2.auth.telegram.initiate","v2.auth.telegram.poll"],"description":"Telegram passwordless login (initiate, long polling)"}},{"alias":"auth.user.apikey:API","category":"API","pattern":{"endpoint":"v2.auth.apikey.*"},"meta":{"endpoints":["v2.auth.apikey.create","v2.auth.apikey.list","v2.auth.apikey.revoke"],"description":"Manage own API keys (auto-filtered by account)"}},{"alias":"auth.user.basic:API","category":"API","pattern":{"endpoint":"v2.auth.basic.*"},"meta":{"endpoints":["v2.auth.basic.create","v2.auth.basic.list","v2.auth.basic.revoke"],"description":"Manage own Basic Auth credentials (auto-filtered by account)"}},{"alias":"auth.user.password:API","category":"API","pattern":{"endpoint":"v2.auth.password.change"},"meta":{"endpoints":["v2.auth.password.change"],"description":"Change own password"}},{"alias":"auth.user.session:API","category":"API","pattern":{"endpoint":"v2.auth.session.signout"},"meta":{"endpoints":["v2.auth.session.signout"],"description":"Logout (revoke session)"}},{"alias":"authenticated:ACCOUNT","category":"ACCOUNT","pattern":{"categories":"!{Anonymous,Shadow}"},"meta":{"description":"Authenticated users (excludes Anonymous and Shadow)"}},{"alias":"billing:API","category":"API","pattern":{"endpoint":"v2.billing.*"},"meta":null},{"alias":"chrono.user.events:API","category":"API","pattern":{"endpoint":"v2.chrono.*"},"meta":{"endpoint":"v2.chrono.*","description":"User event management (auto-filtered by account)"}},{"alias":"geo:API","category":"API","pattern":{"endpoint":"v2.geo.*"},"meta":null},{"alias":"own-bookings:READ","category":"READ","pattern":{"class":"booking","owner":"$account"},"meta":{"description":"свои записи"}},{"alias":"payment.callback:API","category":"API","pattern":{"endpoint":"v2.payment.callback.*"},"meta":{"endpoints":["v2.payment.callback.yookassa","v2.payment.callback.robokassa"],"description":"Payment provider webhooks (YOOKASSA, ROBOKASSA)"}},{"alias":"payment:API","category":"API","pattern":{"endpoint":"v2.payment.*"},"meta":{"endpoints":["v2.payment.create"],"description":"Create payment (authenticated users only)"}},{"alias":"shop:API","category":"API","pattern":{"endpoint":"booking.*"},"meta":{"description":"Booking service endpoints"}}]$j$);
create table "<SCHEMA>"."Rule" (account varchar(255), resource varchar(255), permission varchar(255), weight integer, meta jsonb, enabled boolean);
insert into "<SCHEMA>"."Rule" select * from json_populate_recordset(null::"<SCHEMA>"."Rule", $j$[{"account":"anonymous:ACCOUNT","resource":"auth.telegram:API","permission":"allow","weight":105,"meta":{"description":"Anonymous users can login via Telegram (initiate, poll)"},"enabled":true},{"account":"any:ACCOUNT","resource":"any:API","permission":"deny","weight":0,"meta":{"code":403,"message":"Access denied - default for any ACCOUNT to any API"},"enabled":true},{"account":"any:ACCOUNT","resource":"auth.anonymous:API","permission":"allow","weight":105,"meta":{"description":"Anonymous users can signup, signin, reset password, use OTP"},"enabled":true},{"account":"authenticated:ACCOUNT","resource":"auth.user.apikey:API","permission":"allow","weight":90,"meta":{"description":"Users can manage their own API keys (service auto-filters by ctx.meta.$account.id)"},"enabled":true},{"account":"authenticated:ACCOUNT","resource":"auth.user.basic:API","permission":"allow","weight":90,"meta":{"description":"Users can manage their own Basic Auth (service auto-filters by ctx.meta.$account.id)"},"enabled":true},{"account":"authenticated:ACCOUNT","resource":"auth.user.password:API","permission":"allow","weight":90,"meta":{"description":"Users can change their own password"},"enabled":true},{"account":"authenticated:ACCOUNT","resource":"auth.user.session:API","permission":"allow","weight":90,"meta":{"description":"Users can logout (revoke their session)"},"enabled":true},{"account":"authenticated:ACCOUNT","resource":"billing:API","permission":"allow","weight":90,"meta":{"description":"Users can access billing (uses ctx.meta.$account.id)"},"enabled":true},{"account":"authenticated:ACCOUNT","resource":"chrono.user.events:API","permission":"allow","weight":90,"meta":{"description":"Users can manage their own scheduled events (filtered by ctx.meta.$account.id)"},"enabled":true},{"account":"authenticated:ACCOUNT","resource":"geo:API","permission":"allow","weight":90,"meta":{"description":"Users can access geo (uses ctx.meta.$account.id)"},"enabled":true},{"account":"authenticated:ACCOUNT","resource":"own-bookings:READ","permission":"allow","weight":50,"meta":{"description":"клиент видит свои записи"},"enabled":true},{"account":"authenticated:ACCOUNT","resource":"payment:API","permission":"allow","weight":90,"meta":{"description":"Users can create payments (uses ctx.meta.$account.id)"},"enabled":true},{"account":"authenticated:ACCOUNT","resource":"shop:API","permission":"allow","weight":90,"meta":{"description":"Users can access booking"},"enabled":true}]$j$);
